function size(cfg) {
  const clientPool = Math.ceil(
    (cfg.concurrentReqs * cfg.dbCallsPerReq * cfg.avgQueryMs) / cfg.requestBudgetMs
  );
  const ceiling = cfg.cores * 2 + cfg.spindles;
  const defaultPoolSize = Math.ceil(ceiling * 1.5);
  const usableMax = cfg.maxConnections - cfg.superuserReserved;
  const backendDemand = cfg.pools * defaultPoolSize;
  const fits = backendDemand <= usableMax;
  return { clientPool, defaultPoolSize, backendDemand, usableMax, fits };
}

const r = size({
  concurrentReqs: 200,
  dbCallsPerReq: 3,
  avgQueryMs: 4,
  requestBudgetMs: 100,
  cores: 8,
  spindles: 0,
  pools: 1,
  maxConnections: 100,
  superuserReserved: 3,
});

console.log(
  `clientPool=${r.clientPool} defaultPoolSize=${r.defaultPoolSize} backendDemand=${r.backendDemand} usableMax=${r.usableMax} fits=${r.fits}`
);
